<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/common.php';$actorId=dxf_admin_guard($pdo,DXF_PERMISSION_AUDIT);$events=$pdo->query('SELECT e.id,e.event_key,e.submission_id,e.template_id,e.actor_user_id,e.ip_hash,e.user_agent_hash,e.created_at_utc,v.display_title AS title FROM dxf_submission_events e JOIN dxf_template_versions v ON v.id=e.template_version_id AND v.template_id=e.template_id ORDER BY e.id DESC LIMIT 200')->fetchAll(PDO::FETCH_ASSOC)?:[];
?>
<div class="dxf-admin"><?php dxf_admin_nav($pdo,$actorId,'audit');?><header class="dxf-admin-head"><div><span><?=dxf_h(dxf_t('Privacy-safe trail'))?></span><h1><?=dxf_h(dxf_t('Audit'))?></h1><p><?=dxf_h(dxf_t('Append-only domain events with hashed network identifiers.'))?></p></div></header><section class="dxf-admin-card"><div class="dxf-admin-table"><table class="adam-table"><thead><tr><th><?=dxf_h(dxf_t('Event'))?></th><th><?=dxf_h(dxf_t('Template'))?></th><th><?=dxf_h(dxf_t('Submission'))?></th><th><?=dxf_h(dxf_t('Actor'))?></th><th><?=dxf_h(dxf_t('Request hashes'))?></th><th><?=dxf_h(dxf_t('Time'))?></th></tr></thead><tbody><?php foreach($events as $event):?><tr><td><?=dxf_h($event['event_key'])?></td><td><?=dxf_h($event['title'])?></td><td><?= $event['submission_id']?'#'.(int)$event['submission_id']:'-' ?></td><td><?= $event['actor_user_id']?'#'.(int)$event['actor_user_id']:dxf_h(dxf_t('Public user')) ?></td><td><code><?=dxf_h(substr($event['ip_hash'],0,12))?>…</code> <code><?=dxf_h(substr($event['user_agent_hash'],0,12))?>…</code></td><td><?=dxf_h(dxf_admin_datetime($event['created_at_utc']))?></td></tr><?php endforeach;?></tbody></table></div></section></div>
